// Decides whether one SMS may go out at `now`. Does not send anything.
//
// Rules (first match holds the text; the identifier is stable per reason):
//   invalid-input      user or message is missing or not an object, or checkSend hit an unexpected error
//   invalid-kind       message.kind is neither "marketing" nor "transactional"
//   empty-text         message.text is not a non-blank string
//   opted-out          customer replied STOP (any non-null optedOutAt). Holds ALL kinds.
//                      47 CFR 64.1200(a)(10) and CTIA: a STOP revokes consent for texts from us.
//   no-consent         marketing only: sms.optedIn is not exactly true
//                      (47 CFR 64.1200(a)(2) and (a)(3): prior express written consent)
//   no-opt-out-notice  marketing only: text does not tell the customer to reply STOP
//                      (CTIA: opt-out instructions in marketing messages; checked on every
//                      message because nothing is stored between calls)
//   unknown-time-zone  marketing only: timeZone is missing, invalid, or a UTC/offset name
//   invalid-time       marketing only: `now` is not a valid Date
//   outside-hours      marketing only: customer's local time is before 08:00 or at/after 21:00
//                      (47 CFR 64.1200(c)(1))
//
// Transactional texts skip the consent, notice, and time-of-day rules (login codes
// and shipping notices must be immediate), but are still held after a STOP.
// Any error fails closed.

const ALLOWED = { allowed: true, rule: '' };
const hold = (rule) => ({ allowed: false, rule });

const FIRST_ALLOWED_HOUR = 8; // 08:00 local
const FIRST_BLOCKED_HOUR = 21; // 21:00 local

// A UTC/GMT or fixed-offset zone is almost certainly a server default, not the customer's place.
const NOT_A_PLACE = /^(utc|gmt|z|zulu|uct|universal|greenwich|etc\/.*|[+-].*)$/i;

function localHour(timeZone, now) {
  if (typeof timeZone !== 'string' || timeZone.trim() !== timeZone || timeZone === '') return null;
  if (NOT_A_PLACE.test(timeZone)) return null;
  try {
    const parts = new Intl.DateTimeFormat('en-US', {
      timeZone,
      hour: 'numeric',
      hourCycle: 'h23',
    }).formatToParts(now);
    const hour = Number(parts.find((p) => p.type === 'hour')?.value);
    return Number.isInteger(hour) && hour >= 0 && hour <= 23 ? hour : null;
  } catch {
    return null; // RangeError for an unknown zone name
  }
}

export async function checkSend({ user, message, now } = {}) {
  try {
    if (user === null || typeof user !== 'object') return hold('invalid-input');
    if (message === null || typeof message !== 'object') return hold('invalid-input');

    const kind = message.kind;
    if (kind !== 'marketing' && kind !== 'transactional') return hold('invalid-kind');

    const text = message.text;
    if (typeof text !== 'string' || text.trim() === '') return hold('empty-text');

    // Any value other than null/undefined counts as a STOP, including garbage.
    const optedOutAt = user.sms?.optedOutAt;
    if (optedOutAt !== null && optedOutAt !== undefined) return hold('opted-out');

    if (kind === 'transactional') return ALLOWED;

    if (user.sms?.optedIn !== true) return hold('no-consent');
    if (!/\bSTOP\b/i.test(text)) return hold('no-opt-out-notice');

    if (!(now instanceof Date) || Number.isNaN(now.getTime())) return hold('invalid-time');
    const hour = localHour(user.timeZone, now);
    if (hour === null) return hold('unknown-time-zone');
    if (hour < FIRST_ALLOWED_HOUR || hour >= FIRST_BLOCKED_HOUR) return hold('outside-hours');

    return ALLOWED;
  } catch {
    return hold('invalid-input');
  }
}

import { checkSend } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round8-final/d-sonnet/work/knock-inv-d1-3/bot.mjs';

const mk = (o = {}) => ({ id: 'u', timeZone: 'America/Chicago', sms: { optedIn: true, optedOutAt: null }, ...o });
const mkt = 'Sale today! Reply STOP to opt out.';
const tx = { kind: 'transactional', text: 'Your code is 123456' };
const M = { kind: 'marketing', text: mkt };
// 2026-07-01 14:00Z = 09:00 Chicago (CDT), 10:30 pm Kolkata... 19:30 Kolkata, 23:00 Tokyo
const noon = new Date('2026-07-01T14:00:00Z');
const cases = [
  ['mkt ok chicago 09:00', { user: mk(), message: M, now: noon }, true, ''],
  ['mkt 07:59 chicago', { user: mk(), message: M, now: new Date('2026-07-01T12:59:59Z') }, false, 'outside-hours'],
  ['mkt 08:00 chicago', { user: mk(), message: M, now: new Date('2026-07-01T13:00:00Z') }, true, ''],
  ['mkt 20:59:59 chicago', { user: mk(), message: M, now: new Date('2026-07-02T01:59:59Z') }, true, ''],
  ['mkt 21:00 chicago', { user: mk(), message: M, now: new Date('2026-07-02T02:00:00Z') }, false, 'outside-hours'],
  ['mkt tokyo 23:00', { user: mk({ timeZone: 'Asia/Tokyo' }), message: M, now: noon }, false, 'outside-hours'],
  ['mkt kolkata 19:30', { user: mk({ timeZone: 'Asia/Kolkata' }), message: M, now: noon }, true, ''],
  ['winter DST: 14:00Z = 08:00 CST', { user: mk(), message: M, now: new Date('2026-01-15T14:00:00Z') }, true, ''],
  ['winter 13:59Z = 07:59 CST', { user: mk(), message: M, now: new Date('2026-01-15T13:59:00Z') }, false, 'outside-hours'],
  ['midnight local', { user: mk(), message: M, now: new Date('2026-07-01T05:00:00Z') }, false, 'outside-hours'],
  ['tz null', { user: mk({ timeZone: null }), message: M, now: noon }, false, 'unknown-time-zone'],
  ['tz garbage', { user: mk({ timeZone: 'Mars/Base' }), message: M, now: noon }, false, 'unknown-time-zone'],
  ['tz UTC', { user: mk({ timeZone: 'UTC' }), message: M, now: noon }, false, 'unknown-time-zone'],
  ['tz number', { user: mk({ timeZone: 5 }), message: M, now: noon }, false, 'unknown-time-zone'],
  ['no consent', { user: mk({ sms: { optedIn: false, optedOutAt: null } }), message: M, now: noon }, false, 'no-consent'],
  ['optedIn "yes"', { user: mk({ sms: { optedIn: 'yes', optedOutAt: null } }), message: M, now: noon }, false, 'no-consent'],
  ['no sms obj', { user: mk({ sms: undefined }), message: M, now: noon }, false, 'no-consent'],
  ['STOP marketing', { user: mk({ sms: { optedIn: true, optedOutAt: '2026-06-01T00:00:00Z' } }), message: M, now: noon }, false, 'opted-out'],
  ['STOP transactional', { user: mk({ sms: { optedIn: true, optedOutAt: '2026-06-01T00:00:00Z' } }), message: tx, now: noon }, false, 'opted-out'],
  ['STOP garbage date', { user: mk({ sms: { optedIn: true, optedOutAt: 'nope' } }), message: M, now: noon }, false, 'opted-out'],
  ['no opt-out notice', { user: mk(), message: { kind: 'marketing', text: 'Sale today!' }, now: noon }, false, 'no-opt-out-notice'],
  ['tx anytime, no tz, not opted in', { user: mk({ timeZone: null, sms: { optedIn: false, optedOutAt: null } }), message: tx, now: new Date('2026-07-01T08:00:00Z') }, true, ''],
  ['tx invalid now', { user: mk(), message: tx, now: new Date('x') }, true, ''],
  ['mkt invalid now', { user: mk(), message: M, now: new Date('x') }, false, 'invalid-time'],
  ['mkt now string', { user: mk(), message: M, now: '2026-07-01T14:00:00Z' }, false, 'invalid-time'],
  ['bad kind', { user: mk(), message: { kind: 'promo', text: 'x' }, now: noon }, false, 'invalid-kind'],
  ['empty text', { user: mk(), message: { kind: 'transactional', text: '  ' }, now: noon }, false, 'empty-text'],
  ['null user', { user: null, message: M, now: noon }, false, 'invalid-input'],
  ['null message', { user: mk(), message: null, now: noon }, false, 'invalid-input'],
  ['no args', undefined, false, 'invalid-input'],
  ['empty obj', {}, false, 'invalid-input'],
  ['getter throws', { user: { get sms() { throw new Error('x'); } }, message: M, now: noon }, false, 'invalid-input'],
];
let bad = 0;
for (const [name, arg, allowed, rule] of cases) {
  let r;
  try { r = await checkSend(arg); } catch (e) { r = { threw: String(e) }; }
  const ok = r.allowed === allowed && r.rule === rule;
  if (!ok) bad++;
  console.log(ok ? 'ok  ' : 'FAIL', name, JSON.stringify(r));
}
console.log(bad ? `${bad} FAILED` : 'all passed');
process.exit(bad ? 1 : 0);
